use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let mut non_zero_indices = Vec::new();
    let mut zero_indices = Vec::new();

    for (i, &val) in arr.iter().enumerate() {
        if val.is_u64() {
            if val.to_i64().unwrap() != 0 {
                non_zero_indices.push(i as u64);
            } else {
                zero_indices.push(i as u64);
            }
        }
    }

    let mut result = Value::new_array();
    let mut non_zero_index = 0;
    let mut zero_index = 0;

    for (i, &val) in arr.iter().enumerate() {
        if val.is_u64() {
            if val.to_i64().unwrap() != 0 {
                result.push(Value::new_i64(non_zero_indices[non_zero_index]));
                non_zero_index += 1;
            } else {
                result.push(Value::new_i64(zero_indices[zero_index]));
                zero_index += 1;
            }
        } else {
            result.push(Value::new_i64(val));
        }
    }

    Value::new_array(result)
}
